<?php $page_title='Reports';require_once __DIR__.'/../includes/header.php';$p=$pdo->query("SELECT COUNT(*)v FROM patients")->fetch()['v'];$a=$pdo->query("SELECT COUNT(*)v FROM appointments")->fetch()['v'];$rev=$pdo->query("SELECT COALESCE(SUM(amount),0)v FROM bills WHERE status='paid'")->fetch()['v'];$monthly=$pdo->query("SELECT DATE_FORMAT(created_at,'%Y-%m')m,SUM(amount)t FROM bills WHERE status='paid' GROUP BY m ORDER BY m")->fetchAll();?><h2>Reports</h2><div class="row g-3 my-2"><?php foreach([['Patients',$p],['Appointments',$a],['Paid Revenue','$'.number_format($rev,2)]] as $x):?><div class="col-md-4"><div class="card p-4"><div class="text-muted"><?=$x[0]?></div><div class="stat"><?=$x[1]?></div></div></div><?php endforeach;?></div><div class="card p-4 mt-3"><h5>Monthly Revenue</h5><canvas id="chart" height="100"></canvas></div><script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.4/dist/chart.umd.min.js"></script><script>new Chart(document.getElementById('chart'),{type:'bar',data:{labels:<?=json_encode(array_column($monthly,'m'))?>,datasets:[{label:'Revenue ($)',data:<?=json_encode(array_map('floatval',array_column($monthly,'t')))?>}]}});</script><?php require_once __DIR__.'/../includes/footer.php';?>